using System.Text;
using System.Text.Json;
var temp=Path.Combine(Path.GetTempPath(),"IncomingDisposition-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
var checks=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);checks++;}
async Task Reject(Func<Task> fn,string name){try{await fn();}catch(Exception e)when(e is LibraryBomPermissionException or SimRfqIntakeProblem or IOException or UnauthorizedAccessException){Check(true,name);return;}throw new Exception("FAIL expected rejection: "+name);}
JsonElement J(object o)=>JsonSerializer.SerializeToElement(o,SimLibraryBomStore.Json);
string Token(object o)=>J(o).GetProperty("token").GetString()!;
LibraryPreparation Record(object o)=>J(o).GetProperty("record").Deserialize<LibraryPreparation>(SimLibraryBomStore.Json)!;
string Hash(object o)=>SimLibraryBomStore.Hash(JsonSerializer.SerializeToUtf8Bytes(o,SimLibraryBomStore.Json));
SimPersona P(params string[] rights)=>new("fixture","fixture","Fixture","ACTIVE",[],rights,false,"test");
var tr=P("technical_review.view","technical_review.disposition");var edit=P("assembly_library.view","assembly_library.edit");var view=P("assembly_library.view");
var h=new SimAssemblyHeader("01TEST-18           ","fixture","V1.2","TEST-18     ","D","U*    ","ABC","U*   ",true);var headers=new[]{h};
var p1=Guid.NewGuid().ToString();var p2=Guid.NewGuid().ToString();
var original=Encoding.UTF8.GetBytes("Original incoming workbook fixture");var bytes=original.ToArray();
var d1=new SimRfqIntakeDocument("BOM.xls",bytes.Length,"application/vnd.ms-excel",0,"doc-1","VERIFIED",SharedAcrossProjects:true);
var d2=d1 with{DocumentId="doc-2"};
var source=new PreparationIntake("RFQI-TEST-0049","correlation",new("customer","001","Fixture","fixture"),[new(1,"TEST-18","U ECR 30251",50,p1,"MATERIAL_AND_LABOR"),new(2,"TEST-18","U ECR 30251",20,p2,"MATERIAL_ONLY")],[d1,d2],"TECHNICAL_REVIEW_PENDING");
Task<PreparationIntake> Source(string id)=>Task.FromResult(source);
Task<(SimRfqIntakeDocument Document,byte[] Bytes)> Open(string id,string docId)=>Task.FromResult((source.Files.Single(d=>d.DocumentId==docId),bytes));
SimLibraryPreparation Store()=>new(temp,()=>headers,Source,Open);var store=Store();var library=new SimLibraryBomStore(temp,store.Headers);
PreparationCommand Assessment(object state,int line)=>new(source.IntakeId,line,Token(state),J(state).GetProperty("sourceFingerprint").GetString()!,"SEND",null,"","","",["doc-1","doc-2"],["BUILD_BOM","COMPARE_FILES"]);
async Task<object> Route(int line){var a=await store.Assessment(source.IntakeId,line,tr);return await store.Assess(Assessment(a,line),tr);}
var state=await Route(1);var sibling=await Route(2);var siblingBefore=Hash(Record(sibling));
PreparationFileDispositionCommand Cmd(object state,string decision="DO_NOT_USE",string doc="doc-1")=>new(Record(state).Id,Token(state),doc,decision,true,Guid.NewGuid().ToString());
var legacy=Record(state);var oldJson=JsonSerializer.Serialize(legacy,SimLibraryBomStore.Json);Check(!oldJson.Contains("fileDispositions")&&!oldJson.Contains("disposition"),"untouched legacy null fields omitted from token serialization");
Check(Hash(JsonSerializer.Deserialize<LibraryPreparation>(oldJson,SimLibraryBomStore.Json)!)==Token(state),"legacy record roundtrip hash unchanged");
await Reject(()=>store.Disposition(Cmd(state),view),"Library viewer cannot disposition");
await Reject(()=>store.Disposition(Cmd(state),tr),"Technical Review rights do not grant Library editing");
await Reject(()=>store.Disposition(Cmd(state) with{Confirmed=false},edit),"explicit confirmation required");
await Reject(()=>store.Disposition(Cmd(state) with{Decision="APPROVE"},edit),"approval is not a disposition");
await Reject(()=>store.Disposition(Cmd(state) with{DocumentId="foreign"},edit),"foreign file rejected");
await Reject(()=>store.Disposition(Cmd(state,"ALREADY_IN_RECORDS"),edit),"Already requires explicit Library destination");
var beforeFiles=Hash(Record(state).Files);var reject=Cmd(state);state=await store.Disposition(reject,edit);
Check(Record(state).Status=="NEEDS_PREPARATION","Reject works before Library destination without advancing workflow");
Check(Hash(Record(state).Files)==beforeFiles,"routed evidence references remain intact");
Check(Record(state).FileDispositions!.Single().Decision=="DO_NOT_USE","decision persisted in per-request state");
var package=J(state).GetProperty("incomingPackage");Check(package.GetProperty("files").GetArrayLength()==1&&package.GetProperty("handledFiles").GetArrayLength()==1,"active package removes handled file but retains handled evidence");
Check(package.GetProperty("files")[0].GetProperty("id").GetString()=="doc-2","same filename alone does not hide second file");
Check(package.GetProperty("canDisposition").GetBoolean()&&package.GetProperty("token").GetString()==Token(state),"atomic response supplies current package and concurrency token");
Check(Hash(Record(await store.Assessment(source.IntakeId,2,tr)))==siblingBefore,"shared original file does not leak decision to sibling");
Check((await store.IncomingPackage(source.IntakeId,1,null,tr,"review")).Files.Length==2,"Technical Review retains all original incoming files");
Check((await store.IncomingPackage(source.IntakeId,1,null,tr,"intake")).Files.Length==2,"Intake retains all original incoming files");
Check((await store.IncomingPackageFile("",0,Record(state).Id,"doc-1",view,"library")).Bytes.SequenceEqual(original),"handled evidence remains readable under existing Library rights");
var repeated=await store.Disposition(reject,edit);Check(Token(repeated)==Token(state)&&J(repeated).GetProperty("replayed").GetBoolean(),"exact retry returns saved result without duplicate audit");
await Reject(()=>store.Disposition(reject with{Decision="REOPEN"},edit),"idempotency ID cannot be reused for a different command");
await Reject(()=>store.Disposition(Cmd(state) with{Token=Token(sibling)},edit),"stale preparation token rejected");
var reopen=Cmd(state,"REOPEN");state=await store.Disposition(reopen,edit);Check(Record(state).FileDispositions!.Length==0,"Reopen restores active file");
Check(Record(state).History.Count(e=>e.Disposition is not null)==2,"reopen retains original decision and actor audit");
await Reject(()=>store.Disposition(reject,edit),"delayed pre-reopen retry cannot re-hide file");
Check(Token(await store.Disposition(reopen,edit))==Token(state),"reopen exact retry idempotent");
Check((await Store().IncomingPackage("",0,Record(state).Id,view,"library")).Files.Length==2,"reopen survives store reload");
bytes=Encoding.UTF8.GetBytes("changed source workbook");await Reject(()=>store.Disposition(Cmd(state),edit),"changed source bytes reject decision");bytes=original;
var oldSource=source;source=source with{Assemblies=[source.Assemblies[0] with{Quantity=99},source.Assemblies[1]]};await Reject(()=>store.Disposition(Cmd(state),edit),"changed current project metadata rejects decision");source=oldSource;
source=source with{Assemblies=[source.Assemblies[0],source.Assemblies[1] with{Quantity=99}]};
state=await store.Disposition(Cmd(state,"DO_NOT_USE","doc-2"),edit);Check(Record(state).FileDispositions!.Single().DocumentId=="doc-2","sibling-only change does not block own request");source=oldSource;
state=await store.Disposition(Cmd(state,"REOPEN","doc-2"),edit);
// Test reassessment never applies an old decision to changed bytes under the same document ID.
state=await store.Disposition(Cmd(state),edit);bytes=Encoding.UTF8.GetBytes("same ID new original workbook");source=source with{Files=source.Files.Select(d=>d with{Size=bytes.Length}).ToArray()};
var fresh=await store.Assessment(source.IntakeId,1,tr);state=await store.Assess(Assessment(fresh,1),tr);
Check(Record(state).FileDispositions!.Length==0&&Record(state).History.Any(e=>e.Disposition?.Value.Decision=="DO_NOT_USE"),"reassessment changed hash resets active decision but preserves history");
Check((await store.IncomingPackage("",0,Record(state).Id,view,"library")).Files.Length==2,"reassessed source remains active");
state=await store.Work(new(Record(state).Id,Token(state),"START",Destination:"existing",LibraryKey:h.SourceKeyRaw,DrawingRevision:"U*",BomRevision:"U*"),edit);
Check(Record(state).LibraryKey==h.SourceKeyRaw,"existing destination preserves padded raw key and explicit revision choice");
var already=Cmd(state,"ALREADY_IN_RECORDS");state=await store.Disposition(already,edit,library.ResolvePreparationDocument);
Check(Record(state).FileDispositions!.Single().ExistingDocument is null&&Record(state).FileDispositions!.Single().DrawingRevision=="U*","Already supports explicit user verification without fabricated file match");
await Reject(()=>store.Work(new(Record(state).Id,Token(state),"PROMOTE","doc-1"),edit),"handled file blocked from Save OS copy backend");
bool copied=false;
Task<object> Copy(LibraryPreparation r,PreparationFile f,byte[] b){copied=true;return Task.FromResult<object>(new{ok=true});}
await Reject(()=>store.IncomingFolderCopy(Record(state).Id,Token(state),"doc-1",edit,Copy),"handled file blocks folder preview and copy callback");Check(!copied,"blocked copy never invokes destination access");
await Reject(()=>store.IncomingFolderCopy(Record(state).Id,already.Token,"doc-1",edit,Copy),"pre-issued copy token stale after disposition");
state=await store.Disposition(Cmd(state,"REOPEN"),edit);
await store.IncomingFolderCopy(Record(state).Id,Token(state),"doc-1",edit,Copy);Check(copied,"reopen permits existing copy path without copying real files");
// Saved document fixture: different bytes from incoming; association is user-declared, never equality.
var actor=new LibraryActor("fixture","Fixture",DateTimeOffset.UtcNow);var link=new LibraryFolderLink("link",h.SourceKeyRaw,"TEST-18","U*","U*","fixture-root","Fixture/TEST-18/U","U",actor);
var linked=new SimLinkedSource("fixture-root","Fixture/TEST-18/U/older.xls","link",0,"customer","TEST-18","U*","LIBRARY_DOCUMENT",12,actor.AtUtc,actor.AtUtc,"DIFFERENT_BYTES","source-token","source-selection");
var version=new LibraryDocumentVersion("library-doc",1,link,linked,["BOM_SOURCE"],"MATERIALS","","","UNKNOWN",null,actor);
