var docsPath=Path.Combine(temp,"assembly-library-v1","documents",SimLibraryBomStore.Hash(JsonSerializer.SerializeToUtf8Bytes(new[]{h.SourceKeyRaw,"U*","U*"}))+".json");Directory.CreateDirectory(Path.GetDirectoryName(docsPath)!);await File.WriteAllTextAsync(docsPath,JsonSerializer.Serialize(docs,SimLibraryBomStore.Json));
var documentsBefore=await File.ReadAllBytesAsync(docsPath);var docsToken=Token(await library.Documents(h.SourceKeyRaw,view));
var bom=new LibraryBomDraft("draft", "TEST-18","U*","U*","","PER_ASSEMBLY",false,[],actor,actor);
var bomPath=Path.Combine(temp,"assembly-library-v1",SimLibraryBomStore.Hash(Encoding.UTF8.GetBytes(h.SourceKeyRaw))+".json");
await File.WriteAllTextAsync(bomPath,JsonSerializer.Serialize(new LibraryBomRecord(h.SourceKeyRaw,1,bom,[],[]),SimLibraryBomStore.Json));
var packageVersion=new LibraryPackageVersion("package",1,"SUBMITTED",bom,[],"",actor);
packageVersion=packageVersion with{ContentHash=Hash(new{packageVersion.Bom,packageVersion.Documents,packageVersion.Preparation})};
var packagePath=Path.Combine(temp,"assembly-library-v1","packages",SimLibraryBomStore.Hash(Encoding.UTF8.GetBytes(h.SourceKeyRaw))+".json");Directory.CreateDirectory(Path.GetDirectoryName(packagePath)!);
await File.WriteAllTextAsync(packagePath,JsonSerializer.Serialize(new LibraryPackagesRecord(h.SourceKeyRaw,1,[packageVersion]),SimLibraryBomStore.Json));
var bomBefore=await File.ReadAllBytesAsync(bomPath);var packageBefore=await File.ReadAllBytesAsync(packagePath);
Check(J(await library.Package(h.SourceKeyRaw,view)).GetProperty("locked").GetBoolean(),"isolated submitted package is frozen before disposition");
await File.WriteAllTextAsync(bomPath,JsonSerializer.Serialize(new LibraryBomRecord(h.SourceKeyRaw,2,bom with{DrawingRevision="W"},[],[]),SimLibraryBomStore.Json));
await Reject(()=>store.Disposition(Cmd(state,"ALREADY_IN_RECORDS"),edit,library.ResolvePreparationDocument),"Already without optional reference rejects changed effective Library revision");
await File.WriteAllBytesAsync(bomPath,bomBefore);
var reference=Cmd(state,"ALREADY_IN_RECORDS") with{LibraryDocumentId=version.Id,LibraryDocumentVersion=1,LibraryDocumentsToken=docsToken};
await Reject(()=>store.Disposition(reference with{LibraryDocumentsToken="stale"},edit,library.ResolvePreparationDocument),"stale document set token rejected");
await Reject(()=>store.Disposition(reference with{LibraryDocumentVersion=2},edit,library.ResolvePreparationDocument),"unavailable reference version rejected");
await Reject(()=>store.Disposition(reference with{LibraryDocumentId="foreign"},edit,library.ResolvePreparationDocument),"foreign Library file rejected");
await Reject(()=>store.Disposition(reference with{LibraryDocumentVersion=null},edit,library.ResolvePreparationDocument),"incomplete optional reference rejected");
state=await store.Disposition(reference,edit,library.ResolvePreparationDocument);
var frozen=Record(state).FileDispositions!.Single().ExistingDocument!;Check(frozen.Document.Id==version.Id&&frozen.Document.Version==1&&frozen.LibraryKey==h.SourceKeyRaw,"optional exact saved document version captured");
Check(frozen.Document.Source.Sha256!=Record(state).Files[0].Sha256,"different source bytes do not imply duplicate equivalence or approval");
Check(documentsBefore.SequenceEqual(await File.ReadAllBytesAsync(docsPath)),"disposition leaves identified document ledger byte-identical");
Check(bomBefore.SequenceEqual(await File.ReadAllBytesAsync(bomPath))&&packageBefore.SequenceEqual(await File.ReadAllBytesAsync(packagePath)),"disposition leaves frozen submitted package and BOM bytes unchanged");
docs=docs with{Revision=2,History=[version,version with{Version=2,Use="REFERENCE"}]};await File.WriteAllTextAsync(docsPath,JsonSerializer.Serialize(docs,SimLibraryBomStore.Json));
var reloaded=Record(await Store().Assessment(source.IntakeId,1,tr));Check(reloaded.FileDispositions!.Single().ExistingDocument!.Document.Version==1,"later Library changes cannot remap saved reference");
state=await store.Disposition(Cmd(state,"REOPEN"),edit);
// A locked target record simulates a failed atomic replacement; no success or partial audit.
var recordPath=Path.Combine(temp,"library-preparation-v1",Record(state).Id+".json");var recordBefore=await File.ReadAllBytesAsync(recordPath);
using(var held=new FileStream(recordPath,FileMode.Open,FileAccess.Read,FileShare.Read))await Reject(()=>store.Disposition(Cmd(state),edit),"failed record replacement reports failure");
Check(recordBefore.SequenceEqual(await File.ReadAllBytesAsync(recordPath)),"failed save leaves prior state and audit unchanged");
Check(!Directory.EnumerateFiles(Path.GetDirectoryName(recordPath)!,"*.tmp").Any(),"failed save cleans only its temporary file");
Check(!Directory.Exists(Path.Combine(temp,"library-preparation-v1","evidence")),"dispositions create no OS evidence copies");
Check(Directory.EnumerateFiles(Path.Combine(temp,"assembly-library-v1"),"*",SearchOption.AllDirectories).Count()==3,"only deliberately seeded Library fixtures exist; no folder mutation");
var concurrent1=Cmd(state);var concurrent2=Cmd(state,"DO_NOT_USE","doc-2");
async Task<bool> TrySave(PreparationFileDispositionCommand c){try{await store.Disposition(c,edit);return true;}catch(SimRfqIntakeProblem){return false;}}
var concurrent=await Task.WhenAll(TrySave(concurrent1),TrySave(concurrent2));Check(concurrent.Count(v=>v)==1,"simultaneous saves with same token cannot overwrite each other");
Check((await Store().Queue(view)).GetType() is not null,"saved disposition state readable by existing Library queue");
Console.WriteLine($"PASS {checks} checks; isolated fixture {temp}");
